// Top level for the "ps" build variant: the PC talks to the ZedBoard's own
// USB-UART port (J14), which is wired to the Zynq processor, not to the FPGA logic.
//
// PC --J14--> PS UART1 --ARM bridge program (sw/uart_bridge)--> PS UART0 on EMIO
//    --> top_zedboard (unchanged anti-replay design) --> UART0 --> bridge --> PC
//
// The processor only copies bytes. Every security decision stays in top_zedboard.
// ps_bridge_wrapper is generated by scripts/build.tcl from a block design that
// holds only the Zynq processing system, configured with the ZedBoard preset.
module top_zedboard_ps #(
    parameter W = 64
) (
    // Fixed processor pins (DDR memory and MIO). Vivado assigns their locations.
    inout  wire [14:0] DDR_addr,
    inout  wire [2:0]  DDR_ba,
    inout  wire        DDR_cas_n,
    inout  wire        DDR_ck_n,
    inout  wire        DDR_ck_p,
    inout  wire        DDR_cke,
    inout  wire        DDR_cs_n,
    inout  wire [3:0]  DDR_dm,
    inout  wire [31:0] DDR_dq,
    inout  wire [3:0]  DDR_dqs_n,
    inout  wire [3:0]  DDR_dqs_p,
    inout  wire        DDR_odt,
    inout  wire        DDR_ras_n,
    inout  wire        DDR_reset_n,
    inout  wire        DDR_we_n,
    inout  wire        FIXED_IO_ddr_vrn,
    inout  wire        FIXED_IO_ddr_vrp,
    inout  wire [53:0] FIXED_IO_mio,
    inout  wire        FIXED_IO_ps_clk,
    inout  wire        FIXED_IO_ps_porb,
    inout  wire        FIXED_IO_ps_srstb,
    // FPGA logic pins, as in top_zedboard.
    input  wire        clk,
    input  wire        btn_c,
    input  wire        sw_policy,
    output wire [7:0]  led,
    output wire        oled_sdin,
    output wire        oled_sclk,
    output wire        oled_dc,
    output wire        oled_res,
    output wire        oled_vbat,
    output wire        oled_vdd
);
    wire ps_uart_tx;  // processor UART0 output, into the FPGA logic
    wire ps_uart_rx;  // FPGA logic output, into processor UART0

    ps_bridge_wrapper u_ps (
        .DDR_addr(DDR_addr), .DDR_ba(DDR_ba), .DDR_cas_n(DDR_cas_n),
        .DDR_ck_n(DDR_ck_n), .DDR_ck_p(DDR_ck_p), .DDR_cke(DDR_cke),
        .DDR_cs_n(DDR_cs_n), .DDR_dm(DDR_dm), .DDR_dq(DDR_dq),
        .DDR_dqs_n(DDR_dqs_n), .DDR_dqs_p(DDR_dqs_p), .DDR_odt(DDR_odt),
        .DDR_ras_n(DDR_ras_n), .DDR_reset_n(DDR_reset_n), .DDR_we_n(DDR_we_n),
        .FIXED_IO_ddr_vrn(FIXED_IO_ddr_vrn), .FIXED_IO_ddr_vrp(FIXED_IO_ddr_vrp),
        .FIXED_IO_mio(FIXED_IO_mio), .FIXED_IO_ps_clk(FIXED_IO_ps_clk),
        .FIXED_IO_ps_porb(FIXED_IO_ps_porb), .FIXED_IO_ps_srstb(FIXED_IO_ps_srstb),
        .UART_0_txd(ps_uart_tx),
        .UART_0_rxd(ps_uart_rx)
    );

    top_zedboard #(.W(W)) u_core (
        .clk(clk), .btn_c(btn_c), .sw_policy(sw_policy),
        .uart_rx(ps_uart_tx), .uart_tx(ps_uart_rx),
        .led(led),
        .oled_sdin(oled_sdin), .oled_sclk(oled_sclk), .oled_dc(oled_dc),
        .oled_res(oled_res), .oled_vbat(oled_vbat), .oled_vdd(oled_vdd)
    );
endmodule
